INSERT INTO products (name, description, price, stock, category, image_url, is_new, discount_percentage, created_at)
VALUES ('iPhone 17 Pro', 'Apple iPhone 17 Pro with A19 Pro chip and titanium design.',
        620000.00, 18, 'Phones',
        'https://images.unsplash.com/photo-1759588071781-2c3ba9128497?w=900&q=82&fit=crop&auto=format',
        true, NULL, CURRENT_TIMESTAMP);

INSERT INTO product_storage_options (product_id, sort_order, label, price_delta)
SELECT id, 0, '256GB', 0.00 FROM products WHERE name = 'iPhone 17 Pro';
INSERT INTO product_storage_options (product_id, sort_order, label, price_delta)
SELECT id, 1, '512GB', 50000.00 FROM products WHERE name = 'iPhone 17 Pro';
INSERT INTO product_storage_options (product_id, sort_order, label, price_delta)
SELECT id, 2, '1TB', 100000.00 FROM products WHERE name = 'iPhone 17 Pro';

INSERT INTO product_sim_options (product_id, sort_order, sim_value)
SELECT id, 0, 'Dual eSIM' FROM products WHERE name = 'iPhone 17 Pro';
INSERT INTO product_sim_options (product_id, sort_order, sim_value)
SELECT id, 1, 'Nano-SIM & eSIM' FROM products WHERE name = 'iPhone 17 Pro';

